items.solution:
function groupByActorAndIp(entries) {
  const groups = [];
  for (const entry of entries) {
    const last = groups[groups.length - 1];
    if (last && last.actor === entry.actor && last.sourceIp === entry.sourceIp) {
      last.count += 1;
    } else {
      groups.push({ actor: entry.actor, sourceIp: entry.sourceIp, count: 1 });
    }
  }
  return groups;
}

